let dataset;const $=s=>document.querySelector(s);let metric='MAE';const metrics={MAE:[[2.65,3.80,4.81],[2.58,3.72,4.71]],RMSE:[[4.32,6.16,7.58],[4.34,6.19,7.61]]};function evaluation(){let d=metrics[metric];$('#metricTitle').textContent=metric+' · KSh/kg (lower is better)';$('#metricExplanation').textContent=metric==='MAE'?'Mean absolute error: average size of the error. The baseline has lower MAE at all three horizons.':'Root mean squared error: gives more weight to large errors. The model has slightly lower RMSE at all three horizons.';$('#bars').innerHTML=d[0].map((v,i)=>`<div class="bar-pair"><small>${i+1} month${i?'s':''} ahead</small><div class="bar" style="width:${v/8*100}%">${v.toFixed(2)}</div><div class="bar base" style="width:${d[1][i]/8*100}%">${d[1][i].toFixed(2)}</div></div>`).join('')};document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;document.querySelectorAll('[data-metric]').forEach(x=>x.classList.toggle('active',x===b));evaluation()});evaluation();function render(){let m=$('#market').value,d=dataset[m],history=d.history.map(x=>x.price),all=[...history,...d.forecast],lo=Math.floor((Math.min(...all)-5)/10)*10,hi=Math.ceil((Math.max(...all)+5)/10)*10;let x=i=>55+i*27.2,y=v=>245-(v-lo)/(hi-lo)*210;let line=(a,start=0)=>a.map((v,i)=>`${i?'L':'M'}${x(i+start)},${y(v)}`).join(' ');$('#chartTitle').textContent=m;let svg=`<title>${m}: modeled historical estimates and experimental forecasts in KSh/kg</title><rect x="${x(23)}" y="25" width="90" height="220" fill="#faf0e4"/><text x="610" y="16" fill="#7b8276" font-size="11">Forecast →</text>`;for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4;svg+=`<line x1="55" x2="765" y1="${y(v)}" y2="${y(v)}" stroke="#e4e8df"/><text x="43" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#69766c">${v.toFixed(0)}</text>`}svg+=`<path d="${line(history)}" fill="none" stroke="#224d3b" stroke-width="3"/>`;if($('#baseline').checked)svg+=`<path d="M${x(23)},${y(history[23])}H${x(26)}" stroke="#8e9987" stroke-width="2" stroke-dasharray="4 4"/>`;svg+=`<path d="${line([history[23],...d.forecast],23)}" fill="none" stroke="#bd642e" stroke-width="3" stroke-dasharray="6 4"/>`;d.forecast.forEach((v,i)=>svg+=`<circle cx="${x(24+i)}" cy="${y(v)}" r="5" fill="#bd642e"><title>${['Nov 2026','Dec 2026','Jan 2027'][i]}: KSh ${v.toFixed(2)}/kg</title></circle>`);[[0,'Nov 24'],[6,'May 25'],[12,'Nov 25'],[18,'May 26'],[23,'Oct 26'],[26,'Jan 27']].forEach(([i,t])=>svg+=`<text x="${x(i)}" y="270" font-size="11" text-anchor="middle" fill="#69766c">${t}</text>`);$('#chart').innerHTML=svg;$('#forecastCards').innerHTML=d.forecast.map((v,i)=>`<article><small>${['NOV 2026','DEC 2026','JAN 2027'][i]} · +${i+1}M</small><strong>${v.toFixed(2)}</strong><small>KSh/kg · modeled</small><br><small>Baseline ${history[23].toFixed(2)}</small></article>`).join('');$('#dataTable').innerHTML='<table><thead><tr><th>Month</th><th>Estimate (KSh/kg)</th><th>Type</th></tr></thead><tbody>'+[...d.history.map(v=>[v.date,v.price,'Historical modeled close']),...d.forecast.map((v,i)=>[['2026-11','2026-12','2027-01'][i],v,'Experimental forecast'])].map(r=>`<tr><td>${r[0]}</td><td>${r[1].toFixed(2)}</td><td>${r[2]}</td></tr>`).join('')+'</tbody></table>'}fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{dataset=d;$('#market').innerHTML=Object.keys(d).sort().map(m=>`<option>${m}</option>`).join('');$('#market').value='Kitui';render();$('#market').onchange=render;$('#baseline').onchange=render}).catch(()=>{$('#chartTitle').textContent='Data could not load. Please refresh.'});
